import Link from "next/link";
import type { Metadata } from "next";
import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
import { PREVIEW_GAMES } from "@/components/marketing/gamelanding/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { FaqJsonLd, ProductOffersJsonLd, APP_URL } from "@/components/marketing/StructuredData";

/**
 * LIVE — flagship "Combined" game-landing design, Wave 3 rollout.
 *
 * Unlike the Rust/Palworld pilots, PREVIEW_GAMES.dragonwilds was authored
 * directly from the real seeded GamePlan rows (prisma/seed-wave3-games.ts,
 * 2026-08-31 — 4GB/3-player $8.99, 6GB/5-player $12.99 popular, 8GB/6-player
 * $16.99, the game's current dedicated-server cap), so no price override is
 * needed here.
 *
 * The FAQ + related-links sections below the flagship template are the same
 * pattern as rust-server-hosting/page.tsx, since GameLandingCombined doesn't
 * render its own FAQ/related sections.
 */

export const metadata: Metadata = {
  title: "RuneScape: Dragonwilds Server Hosting — Instant Setup",
  description:
    "Managed RuneScape: Dragonwilds server hosting from $8.99/mo. Full FTP, set your own admin, and instant setup on a low-latency Singapore network.",
  alternates: { canonical: "/dragonwilds-server-hosting" },
  openGraph: {
    type: "article",
    title: "RuneScape: Dragonwilds Server Hosting — Instant Setup",
    description:
      "Managed Dragonwilds hosting: full FTP, set your own admin (OWNER_ID), and instant setup on a low-latency Singapore network. From $8.99/mo.",
    url: `${APP_URL}/dragonwilds-server-hosting`,
  },
};

const GAME = PREVIEW_GAMES.dragonwilds;

const FAQ = [
  {
    q: "What is RuneScape: Dragonwilds?",
    a: "It's Jagex's open-world survival-crafting game set in the RuneScape universe — not the mainline MMO. You explore, gather, craft, build, and fight across a Gielinor-inspired world in third person, either solo or with a small dedicated party.",
  },
  {
    q: "How many players can join a Dragonwilds server?",
    a: "Dragonwilds is built around small, dedicated parties — the game's dedicated server currently caps at 6 players. Our 8 GB / 6-player plan is sized for the full cap, with smaller 3- and 5-player plans if your group is tighter.",
  },
  {
    q: "How do I become admin on my own server?",
    a: "Dragonwilds grants in-game admin based on a Steam64 OWNER_ID set in the server config. Every plan gives you full FTP access, so you can set your own OWNER_ID right after deploy and hold admin from day one — no waiting on a host.",
  },
  {
    q: "Is this a managed server or a VPS I set up myself?",
    a: "It's a fully managed Dragonwilds server. There's no operating system to install — you order a plan and the server is provisioned and online in minutes, ready to connect to from a game panel with full FTP access.",
  },
  {
    q: "How quickly is my server ready?",
    a: "Setup is instant — your Dragonwilds server is provisioned and online within minutes of ordering, so your party can be exploring the same day.",
  },
];

const RELATED = [
  { label: "All game servers", href: "/game-servers" },
  { label: "Sunkenland hosting", href: "/sunkenland-server-hosting" },
  { label: "Core Keeper hosting", href: "/core-keeper-server-hosting" },
  { label: "Pricing", href: "/pricing" },
];

export default function DragonwildsServerHostingPage() {
  return (
    <>
      <FaqJsonLd items={FAQ} />
      <ProductOffersJsonLd
        name="Nxeon RuneScape: Dragonwilds Server Hosting"
        description={GAME.deck}
        url={`${APP_URL}/game-servers`}
        offers={GAME.plans.map((p) => ({
          name: `${GAME.name} ${p.tier} (${p.ram})`,
          price: parseFloat(p.price.replace(/[^0-9.]/g, "")),
        }))}
      />

      <GameLandingCombined game={GAME} reviewBadges={<ReviewBadges />} />

      {/* FAQ */}
      <Section tone="base" size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-3">
          {FAQ.map((f) => (
            <details key={f.q} className="card group">
              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
                <span className="flex items-center justify-between gap-4">
                  {f.q}
                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
                </span>
              </summary>
              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
            </details>
          ))}
        </div>
      </Section>

      {/* Related */}
      <Section tone="base" size="sm">
        <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
          <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
          {RELATED.map((r) => (
            <Link
              key={r.href}
              href={r.href}
              className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
            >
              {r.label}
            </Link>
          ))}
        </div>
      </Section>
    </>
  );
}

