    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/arkasa && docker run -d --name arkasa --restart unless-stopped --stop-timeout 30 -p 7777:7777/udp -p 27020:27020/tcp -e SERVER_MAP='TheIsland_WP' -e SESSION_NAME='Nxeon' -e SERVER_PASSWORD='' -e SERVER_ADMIN_PASSWORD='changeme12' -e GAME_PORT='7777' -e RCON_PORT='27020' -e EXTRA_FLAGS='-WinLiveMaxPlayers=20' -v /opt/arkasa:/home/steam/ark/ShooterGame/Saved sknnr/ark-ascended-server:latest`,
  },
