    family: "soulmask", name: "Soulmask Server", minRamMB: 6144, minDiskGB: 30,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/soulmask && docker run -d --name soulmask --restart unless-stopped -p 8777:8777/udp -p 27015:27015/udp -p 18888:18888/tcp -e SERVER_NAME='Nxeon Soulmask' -e SERVER_PASSWORD='' -e ADMIN_PASSWORD='changeme12' -e GAME_MODE='pve' -e GAME_WORLD='Level01_Main' -e MAX_PLAYERS='40' -e GAME_PORT='8777' -e QUERY_PORT='27015' -e ECHO_PORT='18888' -v /opt/soulmask:/home/soulmask indifferentbroccoli/soulmask-server-docker:latest`,
  },
  {
    family: "dst", name: "Don't Starve Together Server", minRamMB: 2048, minDiskGB: 10,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/dst && docker run -d --name dst --restart unless-stopped -p 10999:10999/udp -e TOKEN='' -e NAME='Nxeon' -e MAX_PLAYERS='10' -e SERVER_PORT='10999' -e GAME_MODE='survival' -v /opt/dst:/data yeetzone/dontstarvetogether:latest`,
  },
  {
    family: "vintagestory", name: "Vintage Story Server", minRamMB: 2048, minDiskGB: 10,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/vintagestory && docker run -d --name vintagestory --restart unless-stopped -p 42420:42420/udp --env UID='1000' --env GID='1000' --env VS_CHANNEL='stable' -v /opt/vintagestory:/vintagestory ich777/vintagestory:latest`,
  },
  {
    family: "necesse", name: "Necesse Server", minRamMB: 1024, minDiskGB: 8,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/necesse && docker run -d --name necesse --restart unless-stopped -p 14159:14159/udp -e WORLD_NAME='Nxeon' -e SERVER_PASSWORD='' -e SERVER_SLOTS='10' -e UPDATE_ON_START='true' -v /opt/necesse:/home/necesse/.config/Necesse andreasgl4ser/necesse-server:latest`,
  },
  {
    family: "tf2", name: "Team Fortress 2 Server", minRamMB: 2048, minDiskGB: 20,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/tf2 && docker run -d --name tf2 --restart unless-stopped -p 27015:27015 -p 27015:27015/udp -p 27020:27020/udp -e SRCDS_TOKEN='' -e SRCDS_RCONPW='changeme12' -e SRCDS_HOSTNAME='Nxeon TF2' -e SRCDS_MAXPLAYERS='24' -e SRCDS_PORT='27015' -e SRCDS_TV_PORT='27020' -v /opt/tf2:/home/steam/tf-dedicated cm2network/tf2:latest`,
  },
  {
    family: "l4d2", name: "Left 4 Dead 2 Server", minRamMB: 2048, minDiskGB: 20,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/l4d2/addons /opt/l4d2/cfg && docker run -d --name l4d2 --restart unless-stopped -p 27015:27015 -p 27015:27015/udp -e HOSTNAME='Nxeon L4D2' -e RCON_PASSWORD='changeme12' -e PORT='27015' -e DEFAULT_MODE='coop' -v /opt/l4d2/addons:/addons -v /opt/l4d2/cfg:/cfg left4devops/l4d2:latest`,
  },
];

type TierSpec = { gameFamily: string; name: string; ramMB: number; cpuCores: number; diskGB: number; slots: number; priceCents: number; featured?: boolean };

const TIERS: TierSpec[] = [
  // ARK: Survival Ascended — priced above ARK: Survival Evolved (prisma/seed-wave1-games.ts:
  // 8GB/20 $14.99, 16GB/50 $27.99, 32GB/100 $49.99) for the heavier UE5 footprint + Wine
  // overhead, similar reasoning to Wave 3's Wine-based Icarus/Sunkenland premium.
  { gameFamily: "arkasa", name: "ARK: Survival Ascended — 8 GB / 10 players", ramMB: 8192, cpuCores: 3, diskGB: 70, slots: 10, priceCents: 1799 },
  { gameFamily: "arkasa", name: "ARK: Survival Ascended — 12 GB / 20 players", ramMB: 12288, cpuCores: 4, diskGB: 90, slots: 20, priceCents: 2699, featured: true },
  { gameFamily: "arkasa", name: "ARK: Survival Ascended — 16 GB / 30 players", ramMB: 16384, cpuCores: 6, diskGB: 120, slots: 30, priceCents: 3699 },

  // Soulmask — large-scale tribal survival, comparable scale/pricing to Conan Exiles
  // (prisma/seed-wave2-games.ts: 6GB/20 $14.99, 8GB/40 $24.99, 12GB/70 $39.99).
  { gameFamily: "soulmask", name: "Soulmask — 6 GB / 20 players", ramMB: 6144, cpuCores: 2, diskGB: 30, slots: 20, priceCents: 1499 },
  { gameFamily: "soulmask", name: "Soulmask — 8 GB / 40 players", ramMB: 8192, cpuCores: 3, diskGB: 45, slots: 40, priceCents: 2299, featured: true },
  { gameFamily: "soulmask", name: "Soulmask — 12 GB / 60 players", ramMB: 12288, cpuCores: 4, diskGB: 65, slots: 60, priceCents: 3499 },

  // Don't Starve Together — lightweight 2D co-op, similar scale/pricing to Core Keeper
  // (prisma/seed-wave3-games.ts: 2GB/6 $4.99, 4GB/8 $7.99, 6GB/8 $11.99).
  { gameFamily: "dst", name: "Don't Starve Together — 2 GB / 6 players", ramMB: 2048, cpuCores: 1, diskGB: 10, slots: 6, priceCents: 499 },
  { gameFamily: "dst", name: "Don't Starve Together — 3 GB / 10 players", ramMB: 3072, cpuCores: 1, diskGB: 15, slots: 10, priceCents: 799, featured: true },
  { gameFamily: "dst", name: "Don't Starve Together — 4 GB / 16 players", ramMB: 4096, cpuCores: 2, diskGB: 20, slots: 16, priceCents: 1099 },

  // Vintage Story — moddable sandbox, similar weight/pricing to Terraria
  // (prisma/seed-gameplans.ts: 2GB/8 $4.49, 4GB/16 $7.99).
  { gameFamily: "vintagestory", name: "Vintage Story — 2 GB / 8 players", ramMB: 2048, cpuCores: 1, diskGB: 10, slots: 8, priceCents: 599 },
  { gameFamily: "vintagestory", name: "Vintage Story — 4 GB / 16 players", ramMB: 4096, cpuCores: 2, diskGB: 20, slots: 16, priceCents: 999, featured: true },
  { gameFamily: "vintagestory", name: "Vintage Story — 6 GB / 16 players", ramMB: 6144, cpuCores: 2, diskGB: 25, slots: 16, priceCents: 1399 },

  // Necesse — very lightweight indie colony survival, similar scale/pricing to Core Keeper.
  { gameFamily: "necesse", name: "Necesse — 1 GB / 6 players", ramMB: 1024, cpuCores: 1, diskGB: 8, slots: 6, priceCents: 449 },
  { gameFamily: "necesse", name: "Necesse — 2 GB / 10 players", ramMB: 2048, cpuCores: 1, diskGB: 12, slots: 10, priceCents: 699, featured: true },
  { gameFamily: "necesse", name: "Necesse — 3 GB / 16 players", ramMB: 3072, cpuCores: 2, diskGB: 18, slots: 16, priceCents: 999 },

  // Team Fortress 2 — classic Source shooter, similar scale/pricing to Garry's Mod
  // (prisma/seed-wave2-games.ts: 2GB/12 $3.99, 4GB/24 $7.99, 6GB/64 $13.99).
  { gameFamily: "tf2", name: "Team Fortress 2 — 2 GB / 16 players", ramMB: 2048, cpuCores: 2, diskGB: 20, slots: 16, priceCents: 599 },
  { gameFamily: "tf2", name: "Team Fortress 2 — 4 GB / 24 players", ramMB: 4096, cpuCores: 3, diskGB: 30, slots: 24, priceCents: 999, featured: true },
  { gameFamily: "tf2", name: "Team Fortress 2 — 6 GB / 32 players", ramMB: 6144, cpuCores: 3, diskGB: 40, slots: 32, priceCents: 1399 },

  // Left 4 Dead 2 — classic Source co-op, small lobbies (4 survivors + up to 4 infected).
  { gameFamily: "l4d2", name: "Left 4 Dead 2 — 2 GB / 8 players", ramMB: 2048, cpuCores: 2, diskGB: 20, slots: 8, priceCents: 499 },
  { gameFamily: "l4d2", name: "Left 4 Dead 2 — 3 GB / 12 players", ramMB: 3072, cpuCores: 2, diskGB: 25, slots: 12, priceCents: 799, featured: true },
  { gameFamily: "l4d2", name: "Left 4 Dead 2 — 4 GB / 16 players", ramMB: 4096, cpuCores: 3, diskGB: 30, slots: 16, priceCents: 1099 },
];

async function main() {
  const templateIdByFamily = new Map<string, string>();
  let sort = 80;
  for (const t of TEMPLATES) {
    const os = await db.osTemplate.upsert({
      where: { slug: t.family },
      create: {
        slug: t.family, name: t.name, category: "APPLICATION", family: t.family, version: "", logo: t.family,
        vmid: 9000, baseVmid: 9000, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB,
        licenseRequired: false, featured: false, sortOrder: sort++, active: true,
      },
      update: { name: t.name, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB, active: true },
    });
    templateIdByFamily.set(t.family, os.id);
    console.log(`  osTemplate ${t.family.padEnd(16)} → ${os.id}`);
  }

  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
  if (plans.length === 0) throw new Error("No active VPS plans — run the main seed first.");
  const largest = plans[plans.length - 1];

  let created = 0, updated = 0;
  const sortByGame = new Map<string, number>();
  for (const spec of TIERS) {
    const basePlan = plans.find((p) => p.ramMB >= spec.ramMB) ?? largest;
    const osId = templateIdByFamily.get(spec.gameFamily) ?? null;
    const sortOrder = sortByGame.get(spec.gameFamily) ?? 0;
    sortByGame.set(spec.gameFamily, sortOrder + 1);
    const data = {
      gameFamily: spec.gameFamily, name: spec.name, ramMB: spec.ramMB, cpuCores: spec.cpuCores, diskGB: spec.diskGB,
      slots: spec.slots, priceCents: spec.priceCents, termMonths: 1, basePlanId: basePlan.id, osTemplateId: osId,
      featured: spec.featured ?? false, active: true, sortOrder,
    };
    const existing = await db.gamePlan.findFirst({ where: { gameFamily: spec.gameFamily, name: spec.name } });
    if (existing) { await db.gamePlan.update({ where: { id: existing.id }, data }); updated++; }
    else { await db.gamePlan.create({ data }); created++; }
    console.log(`  plan ${spec.name.padEnd(42)} base=${basePlan.name}`);
  }
  console.log(`\nWave 4: ${TEMPLATES.length} OsTemplates, GamePlans ${created} created / ${updated} updated.`);
  console.log(`DayZ NOT seeded — non-anonymous Steam login blocker, see file header comment.`);
}

main().catch((e) => { console.error(e); process.exit(1); }).finally(() => db.$disconnect());

